(3719, 413, '_elementor_data', '[{\"id\":\"012bd1e\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"88c6435\",\"elType\":\"widget\",\"settings\":{\"title\":\"\\u041e \\u043d\\u0430\\u0441\",\"align_mobile\":\"center\",\"header_size\":\"h3\",\"align\":\"center\",\"title_color\":\"#1C244B\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Poppins\",\"typography_font_size\":{\"unit\":\"px\",\"size\":48,\"sizes\":[]},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":42,\"sizes\":[]},\"typography_font_size_mobile\":{\"unit\":\"px\",\"size\":\"28\",\"sizes\":[]},\"typography_font_weight\":\"600\",\"typography_text_transform\":\"none\",\"typography_font_style\":\"normal\",\"typography_text_decoration\":\"none\",\"typography_line_height\":{\"unit\":\"em\",\"size\":\"1.2\",\"sizes\":[]},\"typography_line_height_mobile\":{\"unit\":\"em\",\"size\":\"1.1\",\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":\"0\",\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"em\",\"size\":\"0\",\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"3861a55\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<h5>\\u00a0<\\/h5><h5>Sole Fusion: \\u0412\\u0430\\u0448 \\u043d\\u043e\\u0432\\u044b\\u0439 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u043f\\u0440\\u0435\\u043c\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043e\\u0431\\u0443\\u0432\\u0438 \\u0432 \\u0420\\u043e\\u0441\\u0441\\u0438\\u0438<\\/h5><p>\\u00a0<\\/p><p>\\u0422\\u043e\\u043b\\u044c\\u043a\\u043e \\u0447\\u0442\\u043e \\u043e\\u0442\\u043a\\u0440\\u044b\\u0432 \\u0441\\u0432\\u043e\\u0438 \\u0434\\u0432\\u0435\\u0440\\u0438 \\u0432 \\u0420\\u043e\\u0441\\u0441\\u0438\\u0438, Sole Fusion \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442 \\u0432\\u0430\\u043c \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f \\u043a \\u044d\\u043a\\u0441\\u043a\\u043b\\u044e\\u0437\\u0438\\u0432\\u043d\\u043e\\u043c\\u0443 \\u043c\\u0438\\u0440\\u0443 \\u043f\\u0440\\u0435\\u043c\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043e\\u0431\\u0443\\u0432\\u0438 \\u043e\\u0442 \\u0432\\u0435\\u0434\\u0443\\u0449\\u0438\\u0445 \\u043c\\u0438\\u0440\\u043e\\u0432\\u044b\\u0445 \\u0431\\u0440\\u0435\\u043d\\u0434\\u043e\\u0432. \\u041c\\u044b \\u0433\\u043e\\u0440\\u0434\\u0438\\u043c\\u0441\\u044f \\u0442\\u0435\\u043c, \\u0447\\u0442\\u043e \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c \\u0448\\u0438\\u0440\\u043e\\u043a\\u0438\\u0439 \\u0430\\u0441\\u0441\\u043e\\u0440\\u0442\\u0438\\u043c\\u0435\\u043d\\u0442 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 \\u043e\\u0442 Nike \\u0438 New Balance, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0434\\u0440\\u0443\\u0433\\u0438\\u0445 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0431\\u0440\\u0435\\u043d\\u0434\\u043e\\u0432, \\u0442\\u0449\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u043e\\u0442\\u043e\\u0431\\u0440\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0434\\u043b\\u044f \\u0441\\u0430\\u043c\\u044b\\u0445 \\u0432\\u0437\\u044b\\u0441\\u043a\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043f\\u043e\\u043a\\u0443\\u043f\\u0430\\u0442\\u0435\\u043b\\u0435\\u0439.<\\/p><p>\\u00a0<\\/p><p>\\u0412 Sole Fusion \\u043c\\u044b \\u0446\\u0435\\u043d\\u0438\\u043c \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e, \\u0441\\u0442\\u0438\\u043b\\u044c \\u0438 \\u043a\\u043e\\u043c\\u0444\\u043e\\u0440\\u0442. \\u041d\\u0430\\u0448\\u0430 \\u043a\\u043e\\u043b\\u043b\\u0435\\u043a\\u0446\\u0438\\u044f \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 \\u0432 \\u0441\\u0435\\u0431\\u044f \\u043a\\u0430\\u043a \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435, \\u0442\\u0430\\u043a \\u0438 \\u0441\\u0430\\u043c\\u044b\\u0435 \\u043d\\u043e\\u0432\\u044b\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438, \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u044f, \\u0447\\u0442\\u043e \\u0432\\u044b \\u043d\\u0430\\u0439\\u0434\\u0435\\u0442\\u0435 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u0443\\u044e \\u043f\\u0430\\u0440\\u0443 \\u043e\\u0431\\u0443\\u0432\\u0438 \\u0434\\u043b\\u044f \\u043b\\u044e\\u0431\\u043e\\u0433\\u043e \\u0441\\u043b\\u0443\\u0447\\u0430\\u044f \\u2013 \\u043e\\u0442 \\u043f\\u043e\\u0432\\u0441\\u0435\\u0434\\u043d\\u0435\\u0432\\u043d\\u043e\\u0439 \\u043d\\u043e\\u0441\\u043a\\u0438 \\u0434\\u043e \\u0438\\u043d\\u0442\\u0435\\u043d\\u0441\\u0438\\u0432\\u043d\\u044b\\u0445 \\u0442\\u0440\\u0435\\u043d\\u0438\\u0440\\u043e\\u0432\\u043e\\u043a. \\u041c\\u044b \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u0435\\u043c \\u043d\\u0430\\u043f\\u0440\\u044f\\u043c\\u0443\\u044e \\u0441 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c\\u0438, \\u043e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0438\\u0432\\u0430\\u044f \\u043f\\u043e\\u0434\\u043b\\u0438\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u043f\\u0430\\u0440\\u044b \\u043e\\u0431\\u0443\\u0432\\u0438 \\u0438 \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u044f \\u0441\\u0430\\u043c\\u044b\\u0435 \\u0432\\u044b\\u0433\\u043e\\u0434\\u043d\\u044b\\u0435 \\u0446\\u0435\\u043d\\u044b.<\\/p><p>\\u00a0<\\/p><p>\\u041d\\u0430\\u0448\\u0430 \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442\\u043e\\u0432 \\u043f\\u043e \\u043e\\u0431\\u0443\\u0432\\u0438 \\u0432\\u0441\\u0435\\u0433\\u0434\\u0430 \\u0433\\u043e\\u0442\\u043e\\u0432\\u0430 \\u043f\\u043e\\u043c\\u043e\\u0447\\u044c \\u0432\\u0430\\u043c \\u0441 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043e\\u043c, \\u043f\\u0440\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u0432 \\u043f\\u0440\\u04