\\n    };\\r\\n  }\\r\\n\\r\\n  function getWPUserCookie() {\\r\\n    const cookie = document.cookie.split(\';\').find(c => c.trim().startsWith(\'wordpress_logged_in_\'));\\r\\n    if (!cookie) return null;\\r\\n    const parts = cookie.split(\'|\');\\r\\n    return parts.length >= 2 ? {\\r\\n      id: parts[0].split(\'=\')[1],\\r\\n      name: decodeURIComponent(parts[1])\\r\\n    } : null;\\r\\n  }\\r\\n\\r\\n\\r\\n  \\/\\/ 2. \\u0418\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0447\\u0430\\u0442\\u0430\\r\\n  async function initChat() {\\r\\n    const currentUser = await getUser();\\r\\n    console.log(\'\\u041e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c:\', currentUser);\\r\\n    \\r\\n    const socket = io(\'http:\\/\\/localhost:5000\');\\r\\n    \\r\\n    const chat = document.getElementById(\'chat-messages\');\\r\\n    const input = document.getElementById(\'message-input\');\\r\\n    const btn = document.getElementById(\'send-btn\');\\r\\n\\r\\n    \\/\\/ \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a\\u0438 \\u0441\\u043e\\u0431\\u044b\\u0442\\u0438\\u0439\\r\\n    socket.on(\'connect\', () => {\\r\\n      console.log(\'\\u041f\\u043e\\u0434\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043e \\u043a \\u0447\\u0430\\u0442\\u0443 \\u043a\\u0430\\u043a\', currentUser.name);\\r\\n    });\\r\\n\\r\\n    socket.on(\'message_history\', (data) => {\\r\\n      data.messages.forEach(msg => {\\r\\n        addMessage(msg, msg.user_id === currentUser.id ? \'sent\' : \'received\');\\r\\n      });\\r\\n      scrollToBottom();\\r\\n    });\\r\\n\\r\\n    socket.on(\'new_message\', (msg) => {\\r\\n      addMessage(msg, msg.user_id === currentUser.id ? \'sent\' : \'received\');\\r\\n      scrollToBottom();\\r\\n    });\\r\\n\\r\\n    function sendMessage() {\\r\\n      const text = input.value.trim();\\r\\n      if (text) {\\r\\n        socket.emit(\'send_message\', {\\r\\n          text: text,\\r\\n          sender_name: currentUser.name,\\r\\n          user_id: currentUser.id\\r\\n        });\\r\\n        input.value = \'\';\\r\\n      }\\r\\n    }\\r\\n\\r\\n    function addMessage(msg, type) {\\r\\n      const div = document.createElement(\'div\');\\r\\n      div.className = `message ${type}`;\\r\\n      div.innerHTML = `\\r\\n        <strong>${msg.sender}<\\/strong><br>\\r\\n        ${msg.text}<br>\\r\\n        <small>${msg.time}<\\/small>\\r\\n      `;\\r\\n      chat.appendChild(div);\\r\\n    }\\r\\n\\r\\n    function scrollToBottom() {\\r\\n      chat.scrollTop = chat.scrollHeight;\\r\\n    }\\r\\n\\r\\n    btn.addEventListener(\'click\', sendMessage);\\r\\n    input.addEventListener(\'keypress\', (e) => {\\r\\n      if (e.key === \'Enter\') sendMessage();\\r\\n    });\\r\\n    input.focus();\\r\\n  }\\r\\n\\r\\n  \\/\\/ \\u0417\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u043c \\u0447\\u0430\\u0442 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0438 \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u044b\\r\\n  window.addEventListener(\'DOMContentLoaded\', initChat);\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),
