 label {\\r\\n        display: block;\\r\\n        border: 2px solid #eee;\\r\\n        border-radius: 25px;\\r\\n        padding: 15px;\\r\\n        cursor: pointer;\\r\\n        transition: all 0.3s;\\r\\n    }\\r\\n    \\r\\n    .poll-option label:hover {\\r\\n        border-color: #3498db;\\r\\n    }\\r\\n    \\r\\n    .poll-option input[type=\\\"radio\\\"]:checked + label {\\r\\n        border-color: #3498db;\\r\\n        background-color: #f0f8ff;\\r\\n    }\\r\\n    \\r\\n    .poll-option img {\\r\\n        width: 100%;\\r\\n        height: 180px;\\r\\n        object-fit: cover;\\r\\n        border-radius: 5px;\\r\\n        margin-bottom: 10px;\\r\\n    }\\r\\n    \\r\\n    .poll-option span {\\r\\n        display: block;\\r\\n        text-align: center;\\r\\n        font-weight: bold;\\r\\n        color: #2c3e50;\\r\\n    }\\r\\n    \\r\\n    .poll-actions {\\r\\n        display: flex;\\r\\n        justify-content: center;\\r\\n        gap: 15px;\\r\\n        margin-bottom: 30px;\\r\\n    }\\r\\n    \\r\\n    .btn-vote, .btn-results {\\r\\n        padding: 12px 25px;\\r\\n        border: none;\\r\\n        border-radius: 5px;\\r\\n        font-size: 16px;\\r\\n        cursor: pointer;\\r\\n        transition: background 0.3s;\\r\\n    }\\r\\n    \\r\\n    .btn-vote {\\r\\n        background: #3498db;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .btn-vote:hover {\\r\\n        background: #2980b9;\\r\\n    }\\r\\n    \\r\\n    .btn-results {\\r\\n        background: #e74c3c;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .btn-results:hover {\\r\\n        background: #c0392b;\\r\\n    }\\r\\n    \\r\\n    #poll-results {\\r\\n        margin-top: 30px;\\r\\n    }\\r\\n    \\r\\n    #poll-results h3 {\\r\\n        text-align: center;\\r\\n        color: #2c3e50;\\r\\n        margin-bottom: 20px;\\r\\n    }\\r\\n    \\r\\n    .result-chart {\\r\\n        margin-bottom: 20px;\\r\\n    }\\r\\n    \\r\\n    .result-bar {\\r\\n        height: 40px;\\r\\n        background: #3498db;\\r\\n        margin-bottom: 10px;\\r\\n        border-radius: 5px;\\r\\n        position: relative;\\r\\n        transition: width 1s ease-in-out;\\r\\n        display: flex;\\r\\n        align-items: center;\\r\\n        padding: 0 15px;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .dish-name {\\r\\n        flex: 1;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    .dish-percent {\\r\\n        margin: 0 15px;\\r\\n    }\\r\\n    \\r\\n    .dish-votes {\\r\\n        font-size: 14px;\\r\\n    }\\r\\n    \\r\\n    .total-votes {\\r\\n        text-align: center;\\r\\n        font-weight: bold;\\r\\n        color: #7f8c8d;\\r\\n    }\\r\\n    \\r\\n    #poll-message {\\r\\n        padding: 15px;\\r\\n        margin-top: 20px;\\r\\n        border-radius: 5px;\\r\\n        text-align: center;\\r\\n    }\\r\\n    \\r\\n    .success-message {\\r\\n        background: #d4edda;\\r\\n        color: #155724;\\r\\n    }\\r\\n    \\r\\n    .error-message {\\r\\n        background: #f8d7da;\\r\\n        color: #721c24;\\r\\n    }\\r\\n<\\/style>\\r\\n\\r\\n<script>\\r\\ndocument.addEventListener(\'DOMContentLoaded\', function() {\\r\\n    \\/\\/ \\u0425\\u0440\\u0430\\u043d\\u0438\\u043b\\u0438\\u0449\\u0435 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432 \\r\\n    let pollResults = {\\r\\n        \\\"\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c\\\": 0,\\r\\n        \\\"\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435\\\": 0,\\r\\n        \\\"\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439\\\": 0,\\r\\n        \\\"\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439\\\": 0\\r\\n    };\\r\\n    \\r\\n    \\/\\/ \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c, \\u0435\\u0441\\u0442\\u044c \\u043b\\u0438 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u0432 localStorage\\r\\n    if (localStorage.getItem(\'dishPollResults\')) {\\r\\n        pollResults = JSON.parse(localStorage.getItem(\'dishPollResults\'));\\r\\n    }\\r\\n    \\r\\n    const voteBtn = document.getElementById(\'vote-btn\');\\r\\n    const resultsBtn = document.getElementById(\'results-btn\');\\r\\n    const pollResultsDiv = document.getElementById(\'poll-results\');\\r\\n    const messageDiv = document.getElementById(\'poll-message\');\\r\\n    \\r\\n    \\/\\/ \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f\\r\\n    voteBtn.addEventListener(\'click\', function() {\\r\\n        const selectedDish = document.querySelector(\'input[name=\\\"dish\\\"]:checked\');\\r\\n        \\r\\n        if (!selectedDish) {\\r\\n            showMessage(\'\\u041f\\u043e\\u0436\\u0430\\u043b\\u0443\\u0439\\u0441\\u0442\\u0430, \\u0432\\u044b\\u0431\\u0435\\u0440\\u0438\\u0442\\u0435 \\u0431\\u043b\\u044e\\u0434\\u043e!\', \'error\');\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        \\/\\/ \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c, \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043b \\u043b\\u0438 \\u0443\\u0436\\u0435 \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\r\\n        if (localStorage.getItem(\'hasVoted\')) {\\r\\n            showMessage(\'\\u0412\\u044b \\u0443\\u0436\\u0435 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043b\\u0438!\', \'error\');\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        \\/\\/ \\u0423\\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u0432\\u0430\\u0435\\u043c \\u0441\\u0447\\u0435\\u0442\\u0447\\u0438\\u043a \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\r\\n        pollResults[selectedDish.value]++;\\r\\n        \\r\\n        \\/\\/ \\u0421\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u043c \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b\\r\\n        localStorage.setItem(\'dishPollResults\', JSON.stringify(pollResults));\\r\\n        localStorage.setItem(\'hasVoted\', \'true\');\\r\\n        \\r\\n        showMessage(\'\\u0421\\u043f\\u0430\\u0441\\u0438\\u0431\\u043e \\u0437\\u0430 \\u0432\\u0430\\u0448 \\u0433\\u043e\\u043b\\u043e\\u0441!\', \'success\');\\r\\n        updateResults();\\r\\n    });\\r\\n    \\r\\n    \\/\\/ \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a \\u043f\\u0440\\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0430 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432\\r\\n    resultsBtn.addEventListener(\'click\', function() {\\r\\n        updateResults();\\r\\n        pollResultsDiv.style.display = \'block\';\\r\\n    });\\r\\n    \\r\\n    \\/\\/ \\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432\\r\\n    function updateResults() {\\r\\n        const totalVotes = Object.values(pollResults).reduce((a, b) => a + b, 0);\\r\\n        \\r\\n        if (totalVotes === 0) {\\r\\n            document.getElementById(\'total-votes\').textContent = \'0\';\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        document.getElementById(\'total-votes\').textContent = totalVotes;\\r\\n        \\r\\n        \\/\\/ \\u041e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u043c \\u043f\\u0440\\u043e\\u0446\\u0435\\u043d\\u0442\\u044b \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0431\\u043b\\u044e\\u0434\\u0430\\r\\n        for (const dish in pollResults) {\\r\\n            const votes = pollResults[dish];\\r\\n            const percent = Math.round((votes \\/ totalVotes) * 100);\\r\\n            \\r\\n            const bar = document.querySelector(`.result-bar[data-dish=\\\"${dish}\\\"]`);\\r\\n            bar.style.width = `${percent}%`;\\r\\n            bar.querySelector(\'.dish-percent\').textContent = `${percent}%`;\\r\\n            bar.querySelector(\'.dish-votes\').textContent = `(${votes} \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)`;\\r\\n        }\\r\\n    }\\r\\n    \\r\\n    \\/\\/ \\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f \\u043f\\u043e\\u043a\\u0430\\u0437\\u0430 \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u0439\\r\\n    function showMessage(text, type) {\\r\\n        messageDiv.textContent = text;\\r\\n        messageDiv.className = type + \'-message\';\\r\\n        messageDiv.style.display = \'block\';\\r\\n        \\r\\n        setTimeout(function() {\\r\\n            messageDiv.style.display = \'none\';\\r\\n        }, 3000);\\r\\n    }\\r\\n    \\r\\n    \\/\\/ \\u0418\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u043f\\u0440\\u0438 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0435\\r\\n    updateResults();\\r\\n});\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),
(5934, 624, '_elementor_edit_mode', 'builder'),
(5935, 624, '_elementor_template_type', 'wp-page'),
(5936, 624, '_elementor_version', '3.29.2'),
(5937, 624, '_wp_page_template', 'default');
