(6117, 645, '_elementor_data', '[{\"id\":\"d52d82e\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"5c9c454\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>\\u041c\\u044b \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u043c \\u0430\\u0441\\u0441\\u043e\\u0440\\u0442\\u0438\\u043c\\u0435\\u043d\\u0442 \\u0438 \\u0445\\u043e\\u0442\\u0438\\u043c \\u0443\\u0437\\u043d\\u0430\\u0442\\u044c \\u0432\\u0430\\u0448\\u0435 \\u043c\\u043d\\u0435\\u043d\\u0438\\u0435!\\u00a0 \\u0413\\u043e\\u043b\\u043e\\u0441\\u0443\\u0439\\u0442\\u0435 \\u0437\\u0430 \\u0431\\u043b\\u044e\\u0434\\u043e, \\u043a\\u043e\\u0442\\u043e\\u0440\\u043e\\u0435 \\u043f\\u043e\\u044f\\u0432\\u0438\\u0442\\u0441\\u044f \\u0432 \\u043c\\u0435\\u043d\\u044e:<\\/p><p>\\u0412\\u0430\\u0448 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u043f\\u043e\\u043c\\u043e\\u0436\\u0435\\u0442 \\u0441\\u0434\\u0435\\u043b\\u0430\\u0442\\u044c \\u0441\\u0442\\u043e\\u043b\\u043e\\u0432\\u0443\\u044e \\u043b\\u0443\\u0447\\u0448\\u0435!\\u00a0 \\u0421\\u043f\\u0430\\u0441\\u0438\\u0431\\u043e! \\ud83d\\ude0a<\\/p><p><em>#\\u0413\\u043e\\u043b\\u043e\\u0441\\u0443\\u0439_\\u0438_\\u0432\\u043a\\u0443\\u0441\\u043d\\u043e_\\u043f\\u043e\\u0435\\u0448\\u044c<\\/em><\\/p>\",\"_padding\":{\"unit\":\"%\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":\"\"},\"_padding_tablet\":{\"unit\":\"%\",\"top\":\"0\",\"right\":\"5\",\"bottom\":\"0\",\"left\":\"5\",\"isLinked\":\"\"},\"_padding_mobile\":{\"unit\":\"%\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":\"\"},\"align\":\"center\",\"text_color\":\"#324A6D\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Poppins\",\"typography_font_size\":{\"unit\":\"px\",\"size\":22,\"sizes\":[]},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":\"14\",\"sizes\":[]},\"typography_font_weight\":\"300\",\"typography_text_transform\":\"none\",\"typography_font_style\":\"normal\",\"typography_text_decoration\":\"none\",\"typography_line_height\":{\"unit\":\"em\",\"size\":\"1.5\",\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":\"0\",\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"em\",\"size\":\"0\",\"sizes\":[]}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"9238043\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"dish-poll\\\">\\r\\n    <h2>\\u041a\\u0430\\u043a\\u043e\\u0435 \\u0431\\u043b\\u044e\\u0434\\u043e \\u0432\\u044b \\u0445\\u043e\\u0442\\u0438\\u0442\\u0435 \\u0432\\u0438\\u0434\\u0435\\u0442\\u044c \\u0432 \\u043d\\u0430\\u0448\\u0435\\u043c \\u043c\\u0435\\u043d\\u044e?<\\/h2>\\r\\n    <p>\\u041f\\u043e\\u043c\\u043e\\u0433\\u0438\\u0442\\u0435 \\u043d\\u0430\\u043c \\u0432\\u044b\\u0431\\u0440\\u0430\\u0442\\u044c \\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0443\\u044e \\u043d\\u043e\\u0432\\u0438\\u043d\\u043a\\u0443 \\u0434\\u043b\\u044f \\u043d\\u0430\\u0448\\u0435\\u0433\\u043e \\u043c\\u0435\\u043d\\u044e!<\\/p>\\r\\n    \\r\\n    <div class=\\\"poll-options\\\">\\r\\n        <div class=\\\"poll-option\\\">\\r\\n            <input type=\\\"radio\\\" id=\\\"dish1\\\" name=\\\"dish\\\" value=\\\"\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c\\\">\\r\\n            <label for=\\\"dish1\\\">\\r\\n                <img src=\\\"http:\\/\\/localhost\\/wordpress\\/flask\\/img\\/krem-sup-iz-tykvy.jpg\\\" alt=\\\"\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c\\\">\\r\\n                <span>\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c<\\/span>\\r\\n            <\\/label>\\r\\n        <\\/div>\\r\\n        \\r\\n        <div class=\\\"poll-option\\\">\\r\\n            <input type=\\\"radio\\\" id=\\\"dish2\\\" name=\\\"dish\\\" value=\\\"\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435\\\">\\r\\n            <label for=\\\"dish2\\\">\\r\\n                <img src=\\\"http:\\/\\/localhost\\/wordpress\\/flask\\/img\\/kyrgryd.jfif\\\" alt=\\\"\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435\\\">\\r\\n                <span>\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435<\\/span>\\r\\n            <\\/label>\\r\\n        <\\/div>\\r\\n        \\r\\n        <div class=\\\"poll-option\\\">\\r\\n            <input type=\\\"radio\\\" id=\\\"dish3\\\" name=\\\"dish\\\" value=\\\"\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439\\\">\\r\\n            <label for=\\\"dish3\\\">\\r\\n                <img src=\\\"http:\\/\\/localhost\\/wordpress\\/flask\\/img\\/lazan.jpg\\\" alt=\\\"\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439\\\">\\r\\n                <span>\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439<\\/span>\\r\\n            <\\/label>\\r\\n        <\\/div>\\r\\n        \\r\\n        <div class=\\\"poll-option\\\">\\r\\n            <input type=\\\"radio\\\" id=\\\"dish4\\\" name=\\\"dish\\\" value=\\\"\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439\\\">\\r\\n            <label for=\\\"dish4\\\">\\r\\n                <img src=\\\"http:\\/\\/localhost\\/wordpress\\/flask\\/img\\/caption.jpg\\\" alt=\\\"\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439\\\">\\r\\n                <span>\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439<\\/span>\\r\\n            <\\/label>\\r\\n        <\\/div>\\r\\n    <\\/div>\\r\\n    \\r\\n    <div class=\\\"poll-actions\\\">\\r\\n        <button id=\\\"vote-btn\\\" class=\\\"btn-vote\\\">\\u0413\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u0442\\u044c<\\/button>\\r\\n        <button id=\\\"results-btn\\\" class=\\\"btn-results\\\">\\u041f\\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0435\\u0442\\u044c \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b<\\/button>\\r\\n    <\\/div>\\r\\n    \\r\\n    <div id=\\\"poll-results\\\" style=\\\"display: none;\\\">\\r\\n        <h3>\\u0420\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u043e\\u043f\\u0440\\u043e\\u0441\\u0430:<\\/h3>\\r\\n        <div class=\\\"result-chart\\\">\\r\\n            <div class=\\\"result-bar\\\" data-dish=\\\"\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c\\\" style=\\\"width: 0%;\\\">\\r\\n                <span class=\\\"dish-name\\\">\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c<\\/span>\\r\\n                <span class=\\\"dish-percent\\\">0%<\\/span>\\r\\n                <span class=\\\"dish-votes\\\">(0 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)<\\/span>\\r\\n            <\\/div>\\r\\n            <div class=\\\"result-bar\\\" data-dish=\\\"\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435\\\" style=\\\"width: 0%;\\\">\\r\\n                <span class=\\\"dish-name\\\">\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435<\\/span>\\r\\n                <span class=\\\"dish-percent\\\">0%<\\/span>\\r\\n                <span class=\\\"dish-votes\\\">(0 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)<\\/span>\\r\\n            <\\/div>\\r\\n            <div class=\\\"result-bar\\\" data-dish=\\\"\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439\\\" style=\\\"width: 0%;\\\">\\r\\n                <span class=\\\"dish-name\\\">\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439<\\/span>\\r\\n                <span class=\\\"dish-percent\\\">0%<\\/span>\\r\\n                <span class=\\\"dish-votes\\\">(0 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)<\\/span>\\r\\n            <\\/div>\\r\\n            <div class=\\\"result-bar\\\" data-dish=\\\"\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439\\\" style=\\\"width: 0%;\\\">\\r\\n                <span class=\\\"dish-name\\\">\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439<\\/span>\\r\\n                <span class=\\\"dish-percent\\\">0%<\\/span>\\r\\n                <span class=\\\"dish-votes\\\">(0 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)<\\/span>\\r\\n            <\\/div>\\r\\n        <\\/div>\\r\\n        <div class=\\\"total-votes\\\">\\u0412\\u0441\\u0435\\u0433\\u043e \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432: <span id=\\\"total-votes\\\">0<\\/span><\\/div>\\r\\n    <\\/div>\\r\\n    \\r\\n    <div id=\\\"poll-message\\\" style=\\\"display: none;\\\"><\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<style>\\r\\n    #dish-poll {\\r\\n        max-width: 800px;\\r\\n        margin: 30px auto;\\r\\n        font-family: Arial, sans-serif;\\r\\n        padding: 20px;\\r\\n        background: #fff;\\r\\n        border-radius: 25px;\\r\\n        box-shadow: 0 2px 15px rgba(0,0,0,0.1);\\r\\n    }\\r\\n    \\r\\n    #dish-poll h2 {\\r\\n        color: #2c3e50;\\r\\n        text-align: center;\\r\\n        margin-bottom: 10px;\\r\\n    }\\r\\n    \\r\\n    #dish-poll p {\\r\\n        text-align: center;\\r\\n        color: #7f8c8d;\\r\\n        margin-bottom: 30px;\\r\\n    }\\r\\n    \\r\\n    .poll-options {\\r\\n        display: grid;\\r\\n        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\\r\\n        gap: 20px;\\r\\n        margin-bottom: 30px;\\r\\n    }\\r\\n    \\r\\n    .poll-option {\\r\\n        position: relative;\\r\\n    }\\r\\n    \\r\\n    .poll-option input[type=\\\"radio\\\"] {\\r\\n        position: absolute;\\r\\n        opacity: 0;\\r\\n    }\\r\\n    \\r\\n    .poll-option label {\\r\\n        display: block;\\r\\n        border: 2px solid #eee;\\r\\n        border-radius: 25px;\\r\\n        padding: 15px;\\r\\n        cursor: pointer;\\r\\n        transition: all 0.3s;\\r\\n    }\\r\\n    \\r\\n    .poll-option label:hover {\\r\\n        border-color: #3498db;\\r\\n    }\\r\\n    \\r\\n    .poll-option input[type=\\\"radio\\\"]:checked + label {\\r\\n        border-color: #3498db;\\r\\n        background-color: #f0f8ff;\\r\\n        \\r\\n    }\\r\\n    \\r\\n    .poll-option img {\\r\\n        width: 100%;\\r\\n        height: 180px;\\r\\n        object-fit: cover;\\r\\n        border-radius: 25px;\\r\\n        margin-bottom: 10px;\\r\\n    }\\r\\n    \\r\\n    .poll-option span {\\r\\n        display: block;\\r\\n        text-align: center;\\r\\n        font-weight: bold;\\r\\n        color: #2c3e50;\\r\\n    }\\r\\n    \\r\\n    .poll-actions {\\r\\n        display: flex;\\r\\n        justify-content: center;\\r\\n        gap: 15px;\\r\\n        margin-bottom: 30px;\\r\\n    }\\r\\n    \\r\\n    .btn-vote, .btn-results {\\r\\n        padding: 12px 25px;\\r\\n        border: none;\\r\\n        border-radius: 25px;\\r\\n        font-size: 16px;\\r\\n        cursor: pointer;\\r\\n        transition: background 0.3s;\\r\\n    }\\r\\n    \\r\\n    .btn-vote {\\r\\n        background: #0AAA09;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .btn-vote:hover {\\r\\n        background: #077a06\\r\\n    }\\r\\n    \\r\\n    .btn-results {\\r\\n        background: #e74c3c;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .btn-results:hover {\\r\\n        background: #c0392b;\\r\\n    }\\r\\n    \\r\\n    #poll-results {\\r\\n        margin-top: 30px;\\r\\n    }\\r\\n    \\r\\n    #poll-results h3 {\\r\\n        text-align: center;\\r\\n        color: #2c3e50;\\r\\n        margin-bottom: 20px;\\r\\n    }\\r\\n    \\r\\n    .result-chart {\\r\\n        margin-bottom: 20px;\\r\\n    }\\r\\n    \\r\\n    .result-bar {\\r\\n        height: 40px;\\r\\n        background: #0AAA09;\\r\\n        margin-bottom: 10px;\\r\\n        border-radius: 25px;\\r\\n        position: relative;\\r\\n        width: 70px;\\r\\n        transition: width 1s ease-in-out;\\r\\n        display: flex;\\r\\n        align-items: center;\\r\\n        padding: 0 15px;\\r\\n        color: white;\\r\\n    }\\r\\n    \\r\\n    .dish-name {\\r\\n        flex: 1;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    .dish-percent {\\r\\n        margin: 0 15px;\\r\\n    }\\r\\n    \\r\\n    .dish-votes {\\r\\n        font-size: 14px;\\r\\n    }\\r\\n    \\r\\n    .total-votes {\\r\\n        text-align: center;\\r\\n        font-weight: bold;\\r\\n        color: #7f8c8d;\\r\\n    }\\r\\n    \\r\\n    #poll-message {\\r\\n        padding: 15px;\\r\\n        margin-top: 20px;\\r\\n        border-radius: 25px;\\r\\n        text-align: center;\\r\\n    }\\r\\n    \\r\\n    .success-message {\\r\\n        background: #d4edda;\\r\\n        color: #155724;\\r\\n    }\\r\\n    \\r\\n    .error-message {\\r\\n        background: #f8d7da;\\r\\n        color: #721c24;\\r\\n    }\\r\\n<\\/style>\\r\\n\\r\\n<script>\\r\\ndocument.addEventListener(\'DOMContentLoaded\', function() {\\r\\n    \\/\\/ \\u0425\\u0440\\u0430\\u043d\\u0438\\u043b\\u0438\\u0449\\u0435 \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432 \\r\\n    let pollResults = {\\r\\n        \\\"\\u041a\\u0440\\u0435\\u043c-\\u0441\\u0443\\u043f \\u0438\\u0437 \\u0442\\u044b\\u043a\\u0432\\u044b \\u0441 \\u0438\\u043c\\u0431\\u0438\\u0440\\u0435\\u043c\\\": 0,\\r\\n        \\\"\\u041a\\u0443\\u0440\\u0438\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u0434\\u043a\\u0438 \\u0432 \\u043c\\u0435\\u0434\\u043e\\u0432\\u043e-\\u0433\\u043e\\u0440\\u0447\\u0438\\u0447\\u043d\\u043e\\u043c \\u0441\\u043e\\u0443\\u0441\\u0435\\\": 0,\\r\\n        \\\"\\u041b\\u0430\\u0437\\u0430\\u043d\\u044c\\u044f \\u0441\\u043e \\u0448\\u043f\\u0438\\u043d\\u0430\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0438\\u043a\\u043e\\u0442\\u0442\\u043e\\u0439\\\": 0,\\r\\n        \\\"\\u0424\\u0430\\u043b\\u0430\\u0444\\u0435\\u043b\\u044c \\u0441 \\u0445\\u0443\\u043c\\u0443\\u0441\\u043e\\u043c \\u0438 \\u043b\\u0435\\u043f\\u0435\\u0448\\u043a\\u043e\\u0439\\\": 0\\r\\n    };\\r\\n    \\r\\n    \\/\\/ \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c, \\u0435\\u0441\\u0442\\u044c \\u043b\\u0438 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u0432 localStorage\\r\\n    if (localStorage.getItem(\'dishPollResults\')) {\\r\\n        pollResults = JSON.parse(localStorage.getItem(\'dishPollResults\'));\\r\\n    }\\r\\n    \\r\\n    const voteBtn = document.getElementById(\'vote-btn\');\\r\\n    const resultsBtn = document.getElementById(\'results-btn\');\\r\\n    const pollResultsDiv = document.getElementById(\'poll-results\');\\r\\n    const messageDiv = document.getElementById(\'poll-message\');\\r\\n    \\r\\n    \\/\\/ \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f\\r\\n    voteBtn.addEventListener(\'click\', function() {\\r\\n        const selectedDish = document.querySelector(\'input[name=\\\"dish\\\"]:checked\');\\r\\n        \\r\\n        if (!selectedDish) {\\r\\n            showMessage(\'\\u041f\\u043e\\u0436\\u0430\\u043b\\u0443\\u0439\\u0441\\u0442\\u0430, \\u0432\\u044b\\u0431\\u0435\\u0440\\u0438\\u0442\\u0435 \\u0431\\u043b\\u044e\\u0434\\u043e!\', \'error\');\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        \\/\\/ \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c, \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043b \\u043b\\u0438 \\u0443\\u0436\\u0435 \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\r\\n        if (localStorage.getItem(\'hasVoted\')) {\\r\\n            showMessage(\'\\u0412\\u044b \\u0443\\u0436\\u0435 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\u0430\\u043b\\u0438!\', \'error\');\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        \\/\\/ \\u0423\\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u0432\\u0430\\u0435\\u043c \\u0441\\u0447\\u0435\\u0442\\u0447\\u0438\\u043a \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432\\r\\n        pollResults[selectedDish.value]++;\\r\\n        \\r\\n        \\/\\/ \\u0421\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u043c \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b\\r\\n        localStorage.setItem(\'dishPollResults\', JSON.stringify(pollResults));\\r\\n        localStorage.setItem(\'hasVoted\', \'true\');\\r\\n        \\r\\n        showMessage(\'\\u0421\\u043f\\u0430\\u0441\\u0438\\u0431\\u043e \\u0437\\u0430 \\u0432\\u0430\\u0448 \\u0433\\u043e\\u043b\\u043e\\u0441!\', \'success\');\\r\\n        updateResults();\\r\\n    });\\r\\n    \\r\\n    \\/\\/ \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a \\u043f\\u0440\\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0430 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432\\r\\n    resultsBtn.addEventListener(\'click\', function() {\\r\\n        updateResults();\\r\\n        pollResultsDiv.style.display = \'block\';\\r\\n    });\\r\\n    \\r\\n    \\/\\/ \\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432\\r\\n    function updateResults() {\\r\\n        const totalVotes = Object.values(pollResults).reduce((a, b) => a + b, 0);\\r\\n        \\r\\n        if (totalVotes === 0) {\\r\\n            document.getElementById(\'total-votes\').textContent = \'0\';\\r\\n            return;\\r\\n        }\\r\\n        \\r\\n        document.getElementById(\'total-votes\').textContent = totalVotes;\\r\\n        \\r\\n        \\/\\/ \\u041e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u043c \\u043f\\u0440\\u043e\\u0446\\u0435\\u043d\\u0442\\u044b \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0431\\u043b\\u044e\\u0434\\u0430\\r\\n        for (const dish in pollResults) {\\r\\n            const votes = pollResults[dish];\\r\\n            const percent = Math.round((votes \\/ totalVotes) * 100);\\r\\n            \\r\\n            const bar = document.querySelector(`.result-bar[data-dish=\\\"${dish}\\\"]`);\\r\\n            bar.style.width = `${percent}%`;\\r\\n            bar.querySelector(\'.dish-percent\').textContent = `${percent}%`;\\r\\n            bar.querySelector(\'.dish-votes\').textContent = `(${votes} \\u0433\\u043e\\u043b\\u043e\\u0441\\u043e\\u0432)`;\\r\\n        }\\r\\n    }\\r\\n    \\r\\n    \\/\\/ \\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f \\u043f\\u043e\\u043a\\u0430\\u0437\\u0430 \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u0439\\r\\n    function showMessage(text, type) {\\r\\n        messageDiv.textContent = text;\\r\\n        messageDiv.className = type + \'-message\';\\r\\n        messageDiv.style.display = \'block\';\\r\\n        \\r\\n        setTimeout(function() {\\r\\n            messageDiv.style.display = \'none\';\\r\\n        }, 3000);\\r\\n    }\\r\\n    \\r\\n    \\/\\/ \\u0418\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u043f\\u0440\\u0438 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0435\\r\\n    updateResults();\\r\\n});\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),
