		<!-- end single menu -->\n	</ul>\n</nav>\n<!-- end master menu -->\n<section></section><style>@media only screen and (min-width: 769px) { .elementor-element-d052931 .aux-burger-box { display: none } }</style>				\n		[bvi text=\"\"]', 'header', '', 'publish', 'closed', 'closed', '', 'header-2', '', '', '2025-06-07 14:36:46', '2025-06-07 11:36:46', '', 0, 'http://localhost/wordpress/?elementor_library=header-2', 0, 'elementor_library', '', 0),
